// STRINGS[lang][key]: per-language view of S.
export const STRINGS = Object.fromEntries(UI_LANGS.map((l, i) => [l, Object.fromEntries(Object.entries(S).map(([k, v]) => [k, v[i]]))]));

export const pickLang = (...cands) => {
  for (const c of cands) {
    const l = String(c || "").toLowerCase().split(/[-_]/)[0];
    const m = l === "nb" || l === "nn" ? "no" : l;
    if (UI_LANGS.includes(m)) return m;
  }
  return DEFAULT_LANG;
};

const fill = (s, vars) => s.replace(/\{(\w+)\}/g, (m, k) => (vars && vars[k] != null ? String(vars[k]) : m));

// t(key, vars) for one language; t.plural(key, n) picks the plural form; t.lang, t.locale.
export function makeT(lang) {
  if (!UI_LANGS.includes(lang)) lang = DEFAULT_LANG;
  const dict = STRINGS[lang], base = STRINGS[DEFAULT_LANG];
  let pr;
  try { pr = new Intl.PluralRules(LOCALES[lang]); } catch { pr = { select: (n) => (n === 1 ? "one" : "other") }; }
  const t = (key, vars) => {
    const v = dict[key] ?? base[key];
    return typeof v === "string" ? fill(v, vars) : v == null ? key : fill(v.other, vars);
  };
  t.plural = (key, n) => {
    const v = dict[key] ?? base[key];
    return typeof v === "string" ? v : v ? v[pr.select(n)] ?? v.other : key;
  };
  t.lang = lang;
  t.locale = LOCALES[lang];
  return t;
}

// Source name for display: "eBay.de (naudotos)" -> "eBay.de (used)". Names stay Lithuanian for stats.
export const sourceLabel = (n, t) => t.lang === DEFAULT_LANG ? n : n
  .replace(/ \(naudotos\)$/, () => ` (${t("src.used")})`)
  .replace(/ dalys$/, () => " " + t("src.parts"))
  .replace(/ sunkvežimiams$/, () => " " + t("src.trucks"));
